    /**
     * Whether the spec names the code. Pixonaut may answer others: the list is extensible.
     */
    public static function isKnown(string $code): bool
    {
        return isset(self::STATUSES[$code]);
    }

    /**
     * The statuses the spec documents the code with; none for a code it does not name.
     *
     * @return list<int>
     */
    public static function statuses(string $code): array
    {
        return self::STATUSES[$code] ?? [];
    }
